function shell(){let el=document.createElement('section');el.className='template-studio';el.id='haxbroTemplateStudio';el.innerHTML='<div class="template-studio-head"><div><div class="template-studio-kicker">JUST ABOVE YOUR APPLICATION</div><h2>Choose or change your app design</h2><p>Pick a ready-made starting point or theme. Your application opens below and stays editable.</p></div><span class="template-count">'+templates.length+' TEMPLATES</span></div><div class="template-filters" id="templateFilters"></div><div class="template-grid" id="templateGrid"></div><div class="template-theme-row"><span class="template-theme-label">DESIGN THEME</span><div id="templateThemes" style="display:flex;gap:6px;flex-wrap:wrap"></div></div><div class="visual-edit-hint"><i></i>After opening: click text in the preview to edit it, or tell KAI what to change.</div>';return el}
