function drawThemes(){document.querySelector('#templateThemes').innerHTML=themes.map(t=>'<button class="theme-chip '+(theme.name===t.name?'active':'')+'" data-theme="'+t.name+'">'+t.name+'</button>').join('');studio.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{theme=themes.find(t=>t.name===b.dataset.theme)||themes[0];drawThemes();if(selected)openTemplate(selected,true)})}
function thumbMarkup(t){const k=t.kind,c=t.cat;const line='<i></i>';if(k==='pro-template'){const l=t.layout||'';if(['analytics','dashboard','monitor','command','admin','inventory'].includes(l))return '<span class="mini-dash"><b></b><span><i></i><i></i><i></i></span></span><span class="mini-stats"><i></i><i></i><i></i></span><span class="mini-chart"><i></i><i></i><i></i><i></i><i></i><i></i></span>';if(['storefront','marketplace','catalog','ordering','compare','subscriptions'].includes(l))return '<span class="mini-top"><b></b><i></i></span><span class="mini-shop"><i></i><i></i><i></i></span><span class="mini-caption"></span>';if(['editor','creative','docs','documents','database','api','repository','reader'].includes(l))return '<span class="mini-top"><b></b><i></i></span><span class="mini-code"><i></i><i></i><i></i><i></i><i></i></span>';if(['inbox','forum','feed','events','membership','profile','directory','workspace'].includes(l))return '<span class="mini-chat"><i></i><i></i><i></i><i></i></span><span class="mini-input"></span>';if(['booking','search','listings','calendar','restaurant','services'].includes(l))return '<span class="mini-top"><b></b><i></i></span><span class="mini-learn"><b></b><span><i></i><i></i><i></i></span></span>';if(['workflow','onboarding','exam','quiz','cards','learning','habits'].includes(l))return '<span class="mini-top"><b></b><i></i></span><span class="mini-dash"><b></b><span><i></i><i></i><i></i></span></span>';if(['finance','ledger','banking','portfolio','calculator'].includes(l))return '<span class="mini-stats"><i></i><i></i><i></i></span><span class="mini-chart"><i></i><i></i><i></i><i></i><i></i><i></i></span>';return '<span class="mini-top"><b></b><i></i></span><span class="mini-hero"><b></b><i></i><i></i><em></em></span><span class="mini-gallery"><i></i><i></i><i></i></span>'}if(String(k).indexOf('ai-')===0||c==='ai')return '<span class="mini-top"><b></b><i></i></span><span class="mini-ai"><b>AI</b><span><i></i><i></i><i></i></span></span><span class="mini-input"></span>';if(['dashboard','inventory','projects','tasks','crm','budget','fitness','meal'].includes(k)||c==='business'||c==='finance'||c==='productivity')return '<span class="mini-dash"><b></b><span><i></i><i></i><i></i></span></span><span class="mini-stats"><i></i><i></i><i></i></span><span class="mini-chart"><i></i><i></i><i></i><i></i><i></i><i></i></span>';if(['store','catalog'].includes(k)||c==='commerce')return '<span class="mini-top"><b></b><i></i></span><span class="mini-shop"><i></i><i></i><i></i></span><span class="mini-caption"></span>';if(['portfolio','landing'].includes(k)||c==='web')return '<span class="mini-top"><b></b><i></i></span><span class="mini-hero"><b></b><i></i><i></i><em></em></span><span class="mini-gallery"><i></i><i></i><i></i></span>';if(['developer','api'].includes(k)||c==='developer')return '<span class="mini-top"><b></b><i></i></span><span class="mini-code"><i></i><i></i><i></i><i></i><i></i></span>';if(['quiz','courses'].includes(k)||c==='education')return '<span class="mini-top"><b></b><i></i></span><span class="mini-learn"><b></b><span><i></i><i></i><i></i></span></span>';if(['community','messenger'].includes(k)||c==='social')return '<span class="mini-chat"><i></i><i></i><i></i><i></i></span><span class="mini-input"></span>';if(['media','events'].includes(k)||c==='media')return '<span class="mini-feature"></span><span class="mini-gallery"><i></i><i></i><i></i></span>';return '<span class="mini-hero"><b></b><i></i><i></i><em></em></span><span class="mini-gallery"><i></i><i></i><i></i></span>'}function drawTiles(){const items=templates.filter(t=>active==='all'||t.cat===active);document.querySelector('#templateGrid').innerHTML=items.map(t=>'<button class="template-tile '+(selected?.id===t.id?'selected':'')+'" data-template="'+t.id+'"><span class="tile-check">✓</span><span class="template-thumb thumb-'+esc(t.cat)+'">'+thumbMarkup(t)+'</span><span class="template-name">'+esc(t.name)+'</span><span class="template-category">'+esc(categories.find(c=>c.id===t.cat)?.label||'Custom')+' <span aria-hidden="true">·</span> Preview</span></button>').join('')||'<div class="template-empty">No templates in this category.</div>';studio.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{selected=templates.find(t=>t.id===b.dataset.template);drawTiles();openTemplate(selected,false)})}
function proTemplateMarkup(t,esc){
const l=t.layout||"portal",cat=t.cat||"custom",name=esc(t.name),desc=esc(t.desc);
const navs={business:["Overview","Customers","Pipeline","Reports"],productivity:["My work","Projects","Board","Calendar"],finance:["Accounts","Transactions","Budgets","Reports"],operations:["Operations","Resources","Alerts","Settings"],commerce:["Discover","Products","Collections","Orders"],ai:["Workspace","Prompts","Knowledge","History"],developer:["Editor","API reference","Logs","Settings"],education:["Courses","Assignments","Progress","Library"],social:["Feed","Explore","Messages","Groups"],media:["Discover","Library","Playlists","Saved"],travel:["Explore","Bookings","Trips","Account"],property:["Listings","Properties","Tenants","Reports"],fitness:["Today","Plans","Activity","Progress"],professional:["Home","Services","Work","Contact"]};
const nav=navs[cat]||["Overview","Workspace","Activity","Settings"];
const stat=(a,b,c)=>'<article class="pstat"><small>'+a+'</small><strong>'+b+'</strong><em>'+c+'</em></article>';
const cards=(items)=>'<div class="pcards">'+items.map((x,i)=>'<article class="pcard"><small>0'+(i+1)+' / '+cat.toUpperCase()+'</small><h3>'+x[0]+'</h3><p>'+x[1]+'</p><button class="paction" data-action="'+x[2]+'">'+x[2]+' →</button></article>').join("")+'</div>';
const table=(heads,rows)=>'<div class="ptable-wrap"><table class="ptable"><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join("")+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join("")+'</tr>').join("")+'</tbody></table></div>';
let mode="workspace",content="",eyebrow=cat.toUpperCase()+" / "+l.toUpperCase();
if(["analytics","dashboard","monitor","command","admin"].includes(l))mode="dashboard";
else if(l==="inventory")mode="inventory";else if(l==="portal")mode="portal";else if(l==="onboarding")mode="onboarding";else if(l==="database")mode="database";else if(l==="api")mode="api";else if(l==="calendar"&&cat==="media")mode="calendar";else if(l==="library"&&cat==="social")mode="library";else if(l==="inbox"&&cat==="social")mode="messaging";else if(l==="crm")mode="crm";else if(l==="inbox")mode="support";else if(["directory","profile"].includes(l))mode="community";
else if(["kanban","workspace"].includes(l))mode="board";
else if(["finance","ledger","banking","portfolio","calculator"].includes(l))mode="finance";
else if(["storefront","marketplace","catalog","ordering","compare","subscriptions"].includes(l))mode="commerce";
else if(["booking","search","listings","calendar","restaurant","services"].includes(l))mode="booking";
else if(l==="chat"||(l==="workflow"&&cat==="ai"))mode="ai";else if(l==="workflow"&&cat==="developer")mode="automation";
else if(["docs","editor","database","api","repository","reader","creative","documents"].includes(l))mode="developer";
else if(["learning","exam","cards","quiz","portal","library"].includes(l))mode="education";
else if(["feed","forum","events","membership"].includes(l))mode="community";
else if(["streaming","podcast","gallery","editorial"].includes(l))mode="media";
else if(cat==="fitness"||l==="habits")mode="fitness";
if(cat==="media"&&mode!=="calendar")mode="media";if(cat==="social"&&!["messaging","library"].includes(mode))mode="community";if(cat==="professional")mode="website";if(cat==="ai"&&["documents","library","creative"].includes(l))mode="ai-tools";
else if(["agency","corporate","launch","pricing","portfolio","services","gallery","restaurant"].includes(l)||cat==="professional")mode="website";
if(mode==="inventory")content='<div class="pstats">'+stat("SKUs","1,248","Sample stock")+stat("Low stock","18","Reorder watch")+stat("Inbound orders","07","Expected deliveries")+'</div><section class="ppanel"><div class="phead"><h2>Stock control</h2><input class="field psearch" id="psearch" placeholder="Search inventory"></div>'+table(["SKU","ITEM","LOCATION","ON HAND","STATUS"],[["SKU-1042","Studio notebook","A-04","124","Healthy"],["SKU-1088","Field bottle","B-12","08","Reorder"],["SKU-1110","Desk organizer","A-09","42","Healthy"]])+'</section><section class="ppanel"><h2>Stock movement</h2>'+cards([["Receive shipment","Record incoming stock and supplier details.","Receive stock"],["Create purchase order","Prepare a reorder for low-stock items.","Create order"]])+'</section>';
if(mode==="portal")content='<div class="pstats">'+stat("People","128","Sample directory")+stat("Requests pending","06","Needs review")+stat("Upcoming dates","04","Next 7 days")+'</div><section class="ppanel"><div class="phead"><h2>Directory and requests</h2><input class="field psearch" id="psearch" placeholder="Search records"></div>'+table(["NAME","TEAM / UNIT","STATUS","NEXT ACTION"],[["Avery Morgan","Operations","Active","View profile"],["Jordan Lee","Design","On leave","Review request"],["Taylor Kim","Finance","Active","View profile"]])+'</section>'+cards([["Requests center","Review submitted requests and approvals.","Open requests"],["Policies and resources","Keep important documents easy to find.","Browse resources"]]);
if(mode==="onboarding")content='<section class="pfeature"><small>WELCOME / SETUP GUIDE</small><h2>Everything in place for a strong start.</h2><p>Guide a new customer or team member through the steps required to get started.</p><div class="pprogress"><b>2 / 5</b><span>Sample completion</span></div></section><section class="ppanel"><h2>Setup checklist</h2>'+[["Create your profile","Add the basic account details"],["Choose preferences","Set your workspace preferences"],["Connect a service","Configure the tools you use"],["Invite your team","Bring collaborators into the workspace"],["Complete setup","Review and confirm your configuration"]].map((x,i)=>'<label class="phabit"><input type="checkbox" '+(i<2?'checked':'')+'><span><b>'+x[0]+'</b><small>'+x[1]+'</small></span></label>').join("")+'</section>';
if(mode==="database")content='<section class="ppanel"><div class="phead"><h2>Database explorer</h2><button class="paction" data-action="Schema refreshed">Refresh schema</button></div><div class="pboard"><div class="plane"><b>TABLES</b><article><strong>customers</strong><small>1,284 rows</small></article><article><strong>orders</strong><small>428 rows</small></article><article><strong>products</strong><small>86 rows</small></article></div><div class="plane"><b>SCHEMA</b><article><strong>id · uuid</strong><small>Primary key</small></article><article><strong>name · text</strong><small>Customer name</small></article><article><strong>created_at · timestamp</strong><small>Created time</small></article></div></div><h2>Query editor</h2><textarea class="pcode" id="peditor">SELECT id, name, created_at\nFROM customers\nORDER BY created_at DESC\nLIMIT 25;</textarea><button class="pill paction" data-action="Query prepared">Run query</button><pre class="poutput" id="poutput">Sample query only. Connect a database to execute live queries.</pre></section>';
if(mode==="api")content='<section class="ppanel"><div class="phead"><h2>HTTP request builder</h2><span class="pro-kicker">API TESTER</span></div><div class="pform"><select class="field"><option>GET</option><option>POST</option><option>PUT</option><option>DELETE</option></select><input class="field" placeholder="https://api.example.com/v1/resource"><button class="pill paction" data-action="Request prepared">Send request</button></div><div class="ptabs"><button class="active">Headers</button><button>Params</button><button>Body</button><button>Auth</button></div><textarea class="pcode" id="peditor" rows="7">{\n  "Accept": "application/json"\n}</textarea><h2>Response</h2><pre class="poutput" id="poutput">No request sent. Add your endpoint and configure authentication before testing.</pre></section>';
if(mode==="calendar")content='<section class="ppanel"><div class="phead"><h2>Publishing calendar</h2><button class="paction" data-action="Content item created">Schedule content</button></div><div class="pboard">'+[["MON","Product update","09:00"],["TUE","Behind the scenes","13:30"],["WED","Community highlight","11:00"],["THU","New release","15:00"],["FRI","Weekly roundup","10:00"]].map(x=>'<div class="plane"><b>'+x[0]+'</b><article><strong>'+x[1]+'</strong><small>'+x[2]+' · Draft</small><button class="paction" data-action="Content item edited">Edit</button></article></div>').join("")+'</div></section>';
if(mode==="messaging")content='<div class="pdev"><aside class="ppanel"><h2>Conversations</h2>'+["Morgan Lee","Sam Rivera","Alex Chen","Jamie Park"].map((x,i)=>'<button class="pnav" data-nav="'+x+'">'+x+'<small> · '+["2 new","Yesterday","Mon","Sun"][i]+'</small></button>').join("")+'</aside><section class="ppanel"><div class="phead"><h2 id="pcontact">Morgan Lee</h2><span class="pro-kicker">DIRECT MESSAGE</span></div><div class="pchat" id="pmessages"><p><b>Morgan</b><br>Can you share the latest update?</p><p><b>You</b><br>Yes, I will send the summary shortly.</p></div><form id="pform" class="pform"><input class="field" name="query" placeholder="Write a message…" required><button class="pill">Send</button></form><p id="pstatus" class="pnote">Messages are local preview content only.</p></section></div>';
if(mode==="library")content='<section class="ppanel"><div class="phead"><h2>Saved collections</h2><input class="field psearch" id="psearch" placeholder="Search saved links"></div>'+cards([["Product research","A collection of useful product references.","Open collection"],["Design inspiration","Interfaces and patterns worth revisiting.","Open collection"],["Reading list","Articles and resources saved for later.","Open collection"]])+'</section><section class="ppanel"><h2>Add a bookmark</h2><form id="pform" class="pform"><input class="field" name="query" placeholder="Title or URL" required><button class="pill">Save bookmark</button></form><p id="pstatus" class="pnote">Bookmarks are stored in this preview session only.</p></section>';

if(mode==="automation")content='<section class="ppanel"><div class="phead"><h2>Automation canvas</h2><button class="paction" data-action="Workflow saved">Save workflow</button></div><div class="pflow">'+[["01","Trigger","When a form is submitted"],["02","Condition","Check whether the request is valid"],["03","Action","Create a record and notify the owner"],["04","Outcome","Return a confirmation"]].map(x=>'<article><b>'+x[0]+'</b><span><strong>'+x[1]+'</strong><small>'+x[2]+'</small></span><button class="paction" data-action="Edited '+x[1]+'">Edit</button></article>').join("")+'</div><div class="phead"><h2>Run history</h2><span class="pro-kicker">SAMPLE LOGS</span></div>'+table(["RUN","TRIGGER","RESULT","TIME"],[["#1042","Form submitted","Success","10:42"],["#1041","New lead","Success","10:18"],["#1040","Schedule","Needs review","09:54"]])+'</section>';
if(mode==="dashboard")content='<div class="pstats">'+stat("Active records","248","Sample data")+stat("Needs attention","12","Review queue")+stat("Completed today","36","Sample activity")+stat("Service health","99.9%","Illustrative")+'</div><section class="ppanel"><div class="phead"><h2>Activity overview</h2><button class="paction" data-action="Date range changed">Change range</button></div><div class="pchart">'+[42,66,54,82,61,92,72,88,58,96,74,86].map((v,i)=>'<i style="height:'+v+'%"><b>'+["J","F","M","A","M","J","J","A","S","O","N","D"][i]+'</b></i>').join("")+'</div></section><section class="ppanel"><h2>Recent activity</h2>'+table(["ITEM","OWNER","STATUS","UPDATED"],[["Workspace review","Operations","In review","Today"],["Monthly report","Finance","Complete","Yesterday"],["New request","Support","Open","Yesterday"]])+'</section>';
if(mode==="support")content='<div class="pstats">'+stat("Open tickets","18","Sample queue")+stat("Waiting on reply","06","Needs attention")+stat("Resolved today","24","Sample activity")+'</div><div class="pdev"><aside class="ppanel"><small>INBOX FILTERS</small>'+["All tickets","Unassigned","Priority","Resolved"].map(x=>'<button class="pnav" data-nav="'+x+'">'+x+'</button>').join("")+'</aside><section class="ppanel"><div class="phead"><h2>Support inbox</h2><input class="field psearch" id="psearch" placeholder="Search tickets"></div>'+table(["REQUEST","CUSTOMER","PRIORITY","STATUS"],[["Cannot access workspace","Morgan Lee","High","Open"],["Billing question","Sam Rivera","Normal","Waiting"],["Feature request","Alex Chen","Low","In review"],["Account setup","Jamie Park","Normal","Resolved"]])+'<div class="phead"><h2>Ticket response</h2><button class="paction" data-action="Ticket assigned">Assign ticket</button></div><textarea class="field" rows="4" placeholder="Write a helpful response…"></textarea><button class="pill paction" data-action="Reply prepared">Prepare reply</button></section></div>';
if(mode==="crm")content='<div class="pstats">'+stat("Contacts","1,284","Sample records")+stat("Open opportunities","36","All stages")+stat("Follow-ups due","08","Action required")+'</div><section class="ppanel"><div class="phead"><h2>Contact directory</h2><input class="field psearch" id="psearch" placeholder="Search contacts"></div>'+table(["CONTACT","ORGANIZATION","STAGE","NEXT STEP"],[["Avery Morgan","Northstar Labs","Qualified","Schedule call"],["Jordan Lee","Fieldwork Studio","Proposal","Send proposal"],["Taylor Kim","Openframe","New","Review request"]])+'</section>'+cards([["Follow-up queue","Keep important customer conversations moving.","Create reminder"],["Opportunity pipeline","Review open deals and their next steps.","Open pipeline"]]);
if(mode==="board")content='<div class="pstats">'+stat("Projects","12","Sample workspace")+stat("In progress","08","Across teams")+stat("Due this week","03","Milestones")+'</div><section class="ppanel"><div class="phead"><h2>Delivery board</h2><button class="paction" data-action="Task created">Add task</button></div><div class="pboard">'+[["TO DO",["Define project scope","Prepare wireframes"]],["IN PROGRESS",["Build dashboard","Review API contract"]],["DONE",["Kickoff completed","Workspace setup"]]].map(col=>'<div class="plane"><b>'+col[0]+'</b>'+col[1].map(x=>'<article><strong>'+x+'</strong><small>Owner · Team member</small><button class="paction" data-action="Moved '+x+'">Move →</button></article>').join("")+'</div>').join("")+'</div></section>';
if(mode==="finance")content='<div class="pstats">'+stat("Available balance","₹12,480","Illustrative")+stat("Income this month","₹8,240","Sample figure")+stat("Expenses this month","₹3,240","Sample figure")+stat("Net cash flow","+₹5,000","Sample calculation")+'</div><section class="ppanel"><h2>Transactions</h2>'+table(["DESCRIPTION","CATEGORY","DATE","AMOUNT"],[["Client payment","Income","Today","+₹4,200"],["Workspace tools","Software","Yesterday","−₹840"],["Travel expense","Travel","18 Nov","−₹1,200"]])+'</section><section class="ppanel"><h2>Add transaction</h2><form id="pform" class="pform"><input class="field" name="query" placeholder="Description" required><input class="field" name="amount" type="number" placeholder="Amount ₹" required><select class="field" name="type"><option>Income</option><option>Expense</option></select><button class="pill">Add record</button></form><p id="pstatus" class="pnote">Sample data only. Entries stay in this preview session.</p><div id="precords"></div></section>';
if(mode==="commerce")content='<section class="pfeature"><small>CURATED COLLECTION</small><h2>Discover the collection.</h2><p>Browse featured products, compare options and build a basket.</p><button class="pill paction" data-action="Collection opened">Explore collection</button></section><div class="phead"><h2>Featured products</h2><input class="field psearch" id="psearch" placeholder="Search products"></div><div class="pproducts">'+[["Studio essentials","Thoughtful everyday objects","₹2,400"],["Signature collection","A considered new release","₹3,800"],["Field edition","Made for work in motion","₹1,650"],["Daily carry","A practical favorite","₹980"]].map((x,i)=>'<article class="pproduct"><div class="part">0'+(i+1)+'</div><small>COLLECTION / 0'+(i+1)+'</small><h3>'+x[0]+'</h3><p>'+x[1]+'</p><b>'+x[2]+'</b><button class="pill paction" data-action="Added '+x[0]+'">Add to basket</button></article>').join("")+'</div><p id="pstatus" class="pnote">Sample products and prices. Basket actions are preview-only.</p>';
if(mode==="booking")content='<section class="pfeature"><small>PLAN YOUR NEXT STEP</small><h2>Find the right option.</h2><p>Search dates, locations and requirements, then review the available choices.</p><form id="pform" class="pform"><input class="field" name="query" placeholder="Location or service" required><input class="field" name="date" type="date"><input class="field" name="quantity" type="number" min="1" value="1"><button class="pill">Search options</button></form><p id="pstatus" class="pnote">Live availability requires a connected provider.</p></section>'+cards([["Featured option","A popular sample choice for this workspace.","View details"],["Flexible option","A flexible option with room to customize.","Check details"],["Premium option","An elevated option with additional features.","Explore option"]]);
if(mode==="ai")content='<div class="pai-grid"><section class="ppanel"><div class="phead"><h2>'+(l==="chat"?"Conversation workspace":"Agent workflow")+'</h2><small>CONFIGURABLE</small></div>'+(l==="chat"?'<div class="pchat" id="pmessages">Welcome to '+name+'. Connect a model to enable real assistant responses.</div><form id="pform" class="pform"><input class="field" name="query" placeholder="Write a message…" required><button class="pill">Send</button></form>':'<div class="pflow">'+[["01","Trigger","When a request arrives"],["02","Reason","Interpret context"],["03","Action","Run selected action"],["04","Review","Return a result"]].map(x=>'<article><b>'+x[0]+'</b><span><strong>'+x[1]+'</strong><small>'+x[2]+'</small></span></article>').join("")+'</div><button class="pill paction" data-action="Workflow step added">Add step</button>')+'</section><aside class="ppanel"><small>CONFIGURATION</small><h2>Workspace settings</h2><label class="plabel">Name<input class="field" value="'+name+'"></label><label class="plabel">Instructions<textarea class="field" rows="4" placeholder="Describe behavior and rules"></textarea></label><label class="plabel">Response style<select class="field"><option>Clear and concise</option><option>Detailed</option><option>Professional</option></select></label><button class="pill paction" data-action="Configuration saved">Save settings</button></aside></div><p id="pstatus" class="pnote">Model responses and connected actions require configured services.</p>';
if(mode==="ai-tools")content='<div class="pai-grid"><section class="ppanel"><div class="phead"><h2>'+(l==="library"?"Prompt collection":l==="creative"?"Image concept studio":"Knowledge sources")+'</h2><small>AI WORKSPACE</small></div>'+(l==="library"?'<input class="field psearch" id="psearch" placeholder="Search prompt recipes"><div class="pfeed"><b>Research brief</b><p>Turn a topic into a structured research plan.</p><button class="paction" data-action="Prompt copied">Use prompt</button></div><div class="pfeed"><b>Product specification</b><p>Convert a product idea into requirements.</p><button class="paction" data-action="Prompt copied">Use prompt</button></div><div class="pfeed"><b>Writing refinement</b><p>Improve clarity, tone and structure.</p><button class="paction" data-action="Prompt copied">Use prompt</button></div>':l==="creative"?'<div class="pfeature"><small>CANVAS PREVIEW</small><h2>Visual direction</h2><p>Describe a concept, define the style and organize your generation history.</p><div class="part" style="height:170px">✦</div></div><label class="plabel">Image brief<textarea class="field" rows="4" placeholder="Describe the image concept, subject and composition"></textarea></label><button class="pill paction" data-action="Image brief prepared">Prepare brief</button>':'<div class="pfeed"><b>Product handbook.pdf</b><p>Sample source · Not connected</p><button class="paction" data-action="Source selected">Select source</button></div><div class="pfeed"><b>Support knowledge base</b><p>Sample source · Not connected</p><button class="paction" data-action="Source selected">Select source</button></div><label class="plabel">Ask your knowledge base<input class="field" placeholder="Ask a question about your sources"></label><button class="pill paction" data-action="Question prepared">Prepare question</button>')+'</section><aside class="ppanel"><small>CONFIGURATION</small><h2>AI settings</h2><label class="plabel">Workspace name<input class="field" value="'+name+'"></label><label class="plabel">Instructions<textarea class="field" rows="4" placeholder="Define how this AI workspace should behave"></textarea></label><label class="plabel">Response style<select class="field"><option>Clear and concise</option><option>Detailed</option><option>Professional</option></select></label><button class="pill paction" data-action="AI settings saved">Save settings</button></aside></div><p id="pstatus" class="pnote">This is a functional interface starter. Connect an AI model and data sources for live intelligence.</p>';
if(mode==="developer")content='<div class="pdev"><aside class="ppanel"><small>PROJECT NAVIGATION</small>'+["Overview","Getting started","Reference","Examples","Settings"].map(x=>'<button class="pnav" data-nav="'+x+'">'+x+'</button>').join("")+'</aside><section class="ppanel"><div class="phead"><h2>'+(l==="api"?"Request builder":l==="database"?"Data explorer":l==="repository"?"Repository":"Workspace editor")+'</h2><button class="paction" data-action="Changes saved">Save</button></div><div class="ptabs"><button class="active">Editor</button><button>Preview</button><button>History</button></div><textarea class="pcode" id="peditor" spellcheck="false">'+(l==="api"?"GET /api/example\nAccept: application/json\n\n// Configure endpoint and headers":l==="database"?"SELECT id, name, status\nFROM records\nORDER BY updated_at DESC;":"// "+t.name+"\n\n// Add your implementation and configuration here.")+'</textarea><pre class="poutput" id="poutput">Ready. Add code, query or request configuration.</pre></section></div>';
if(mode==="education")content='<section class="pfeature"><small>YOUR LEARNING SPACE</small><h2>Build knowledge, one step at a time.</h2><p>Pick up where you left off and keep learning organized.</p><div class="pprogress"><b>68%</b><span>Sample progress</span></div></section><div class="pstats">'+stat("Courses","08","In your library")+stat("In progress","03","Active learning")+stat("Completed","12","Sample records")+'</div>'+cards([["Foundations","A structured introduction to core concepts.","Continue lesson"],["Practical application","Turn knowledge into a working project.","Open module"],["Advanced topics","Guided exercises and deeper study.","Start learning"]]);
if(mode==="community")content='<div class="pcommunity"><section class="ppanel"><h2>Community feed</h2><form id="pform" class="pform"><textarea class="field" name="query" rows="2" placeholder="Share an update…" required></textarea><button class="pill">Publish update</button></form><div id="pfeed">'+[["Community team","Welcome to the space","Share progress, questions and useful ideas."],["Member update","Weekly discussion","What is one thing you learned this week?"],["Events team","Upcoming meetup","Join the next community session."]].map(x=>'<article class="pfeed"><b>'+x[0]+'</b><h3>'+x[1]+'</h3><p>'+x[2]+'</p><button class="paction" data-action="Reply opened">Reply</button></article>').join("")+'</div></section><aside class="ppanel"><h2>Community highlights</h2>'+cards([["Popular topics","Explore active conversations.","Browse topics"],["Upcoming events","See what is happening next.","View events"]])+'</aside></div><p id="pstatus" class="pnote">Posts are preview-only until a community backend is connected.</p>';
if(mode==="media")content='<section class="pfeature"><small>FEATURED COLLECTION</small><h2>Stories worth your time.</h2><p>Explore selected work, new releases and saved favorites.</p><button class="pill paction" data-action="Collection opened">Explore collection</button></section><div class="phead"><h2>Recently added</h2><input class="field psearch" id="psearch" placeholder="Search library"></div><div class="pproducts">'+[["The creative process","Feature story"],["Inside the studio","Behind the scenes"],["New perspectives","Editor selection"],["The next chapter","Latest release"]].map((x,i)=>'<article class="pproduct"><div class="part">'+(i+1)+'</div><small>'+x[1]+'</small><h3>'+x[0]+'</h3><button class="paction" data-action="Opened '+x[0]+'">Open feature →</button></article>').join("")+'</div>';
if(mode==="fitness")content='<div class="pstats">'+stat("Daily movement","7,240 steps","Illustrative")+stat("Weekly target","3 / 4","Workouts completed")+stat("Consistency","5 days","Sample streak")+'</div><section class="ppanel"><h2>Daily routine</h2>'+[["Morning movement","20 minute walk"],["Hydration","Reach your daily water goal"],["Focused session","Complete planned workout"],["Recovery","Stretch and rest"]].map((x,i)=>'<label class="phabit"><input type="checkbox"><span><b>'+x[0]+'</b><small>'+x[1]+'</small></span></label>').join("")+'</section>';
if(mode==="website")content='<section class="pfeature peditorial"><small>INTRODUCING / '+name+'</small><h2>Thoughtful work.<br>Meaningful outcomes.</h2><p>'+desc+' Build a clear story around your services, work and next step.</p><button class="pill paction" data-action="Inquiry started">Start a conversation</button><div class="peditorial-mark">H<span>/</span>B</div></section><section class="ppanel"><h2>Focused capabilities</h2>'+cards([["Strategy & direction","Define the right problem and a practical path forward.","Explore service"],["Design & experience","Create clear, useful and memorable experiences.","View approach"],["Delivery & support","Turn the plan into a working outcome.","Start a project"]])+'</section><section class="ppanel"><h2>Project inquiry</h2><form id="pform" class="pform"><input class="field" name="name" placeholder="Your name" required><input class="field" name="email" type="email" placeholder="Email" required><textarea class="field" name="query" placeholder="Project details" required></textarea><button class="pill">Send inquiry</button></form><p id="pstatus" class="pnote">Preview form only. Connect email or CRM to receive submissions.</p></section>';
if(mode==="workspace")content='<div class="pstats">'+stat("Workspace status","Ready","Starter state")+stat("Open items","06","Sample records")+stat("Recent updates","12","Illustrative")+'</div><section class="ppanel"><h2>Get started</h2>'+cards([[t.name,desc,"Open overview"],["Configure workspace","Set up the structure and preferences.","Configure"],["Connect your workflow","Add the integrations and actions you need.","Connect service"]])+'</section>';
const css='.pro-shell{display:grid;grid-template-columns:205px minmax(0,1fr);min-height:100vh}.pside{padding:25px 14px;border-right:1px solid color-mix(in srgb,var(--ink) 13%,transparent);display:flex;flex-direction:column;gap:5px}.pside strong{font-size:13px;padding:0 9px 24px}.pside small,.pro-kicker,.ppanel>small{font-size:9px;letter-spacing:.14em;color:var(--muted);font-weight:800}.pnav{border:0;background:transparent;text-align:left;padding:10px;border-radius:7px;color:var(--muted);font-size:11px}.pnav:hover{background:color-mix(in srgb,var(--primary) 10%,var(--surface));color:var(--ink)}.pmain{min-width:0;padding:0 28px 36px}.ptop{height:62px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid color-mix(in srgb,var(--ink) 12%,transparent);font-size:10px}.pintro{padding:28px 0 18px}.pintro h1{font-size:clamp(28px,4vw,43px);letter-spacing:-.06em;margin:8px 0}.pintro p,.pcard p,.pproduct p,.pnote{font-size:11px;color:var(--muted);line-height:1.65;max-width:650px}.pstats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:10px 0 16px}.pstat,.ppanel,.pcard,.pproduct{border:1px solid color-mix(in srgb,var(--ink) 12%,transparent);border-radius:11px;background:var(--surface);padding:15px}.pstat small,.pstat em{display:block;color:var(--muted);font-size:9px;font-style:normal}.pstat strong{display:block;font-size:24px;margin:8px 0}.ppanel{margin:13px 0}.phead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.phead h2,.ppanel h2{font-size:16px;margin:5px 0}.pchart{height:150px;display:flex;align-items:end;gap:8px;padding:10px 4px 18px;border-bottom:1px solid color-mix(in srgb,var(--ink) 18%,transparent);background:repeating-linear-gradient(to bottom,transparent 0,transparent 36px,color-mix(in srgb,var(--ink) 7%,transparent) 37px)}.pchart i{flex:1;background:color-mix(in srgb,var(--primary) 70%,var(--surface));border-radius:4px 4px 0 0;position:relative}.pchart b{position:absolute;bottom:-17px;left:50%;transform:translateX(-50%);font-size:8px;color:var(--muted)}.ptable-wrap{overflow:auto}.ptable{width:100%;border-collapse:collapse;font-size:10px;text-align:left}.ptable th,.ptable td{padding:11px 9px;border-bottom:1px solid color-mix(in srgb,var(--ink) 9%,transparent);white-space:nowrap}.ptable th{font-size:8px;color:var(--muted);letter-spacing:.1em}.pcards,.pproducts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.pcard h3,.pproduct h3{font-size:13px;margin:13px 0 6px}.pcard>small,.pproduct>small{font-size:8px;color:var(--muted);letter-spacing:.1em}.paction{border:0;background:transparent;color:var(--primary);padding:8px 0;font-size:10px;cursor:pointer}.pboard{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:10px;overflow:auto}.plane{background:color-mix(in srgb,var(--ink) 4%,var(--surface));border-radius:9px;padding:11px;font-size:9px;letter-spacing:.1em}.plane article{display:grid;gap:8px;background:var(--surface);border:1px solid color-mix(in srgb,var(--ink) 10%,transparent);padding:12px;border-radius:8px;margin-top:9px}.plane article strong{font-size:11px}.plane article small{font-size:9px;color:var(--muted)}.pform{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;align-items:center}.pform textarea{grid-column:1/-1}.psearch{max-width:220px}.pfeature{border:1px solid color-mix(in srgb,var(--ink) 13%,transparent);background:var(--surface);border-radius:13px;padding:24px;margin:16px 0}.pfeature>small{font-size:9px;letter-spacing:.15em;color:var(--primary);font-weight:800}.pfeature h2{font-size:clamp(26px,4vw,42px);margin:10px 0}.pfeature p{font-size:11px;color:var(--muted);max-width:520px;line-height:1.7}.pproduct{padding:0;overflow:hidden}.part{height:120px;background:linear-gradient(135deg,color-mix(in srgb,var(--ink) 12%,var(--surface)),color-mix(in srgb,var(--primary) 14%,var(--surface)));display:grid;place-items:center;font-size:28px;font-weight:850}.pproduct>small,.pproduct h3,.pproduct p,.pproduct>b,.pproduct button{margin-left:12px;margin-right:12px}.pproduct>b{font-size:11px}.pproduct .pill{margin:10px 12px 14px}.pai-grid,.pcommunity,.pdev{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(220px,1fr);gap:12px}.pchat{min-height:190px;background:color-mix(in srgb,var(--ink) 4%,var(--surface));border-radius:8px;padding:15px;margin:12px 0;font-size:11px}.pflow{display:grid;gap:8px;margin:14px 0}.pflow article{display:flex;gap:12px;align-items:center;border:1px solid color-mix(in srgb,var(--ink) 12%,transparent);padding:12px;border-radius:8px}.pflow article>b{background:color-mix(in srgb,var(--primary) 12%,var(--surface));color:var(--primary);padding:8px;border-radius:6px}.pflow span{display:grid;gap:4px}.pflow small,.phabit small{font-size:9px;color:var(--muted)}.plabel{display:grid;gap:6px;margin:12px 0;font-size:10px;color:var(--muted)}.pdev{grid-template-columns:160px minmax(0,1fr)}.ptabs{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid color-mix(in srgb,var(--ink) 12%,transparent)}.ptabs button{border:0;background:transparent;color:var(--muted);font-size:10px}.pcode{width:100%;min-height:240px;background:#101318;color:#f4f6f8;border:1px solid #2b3039;padding:14px;font:12px/1.7 ui-monospace,monospace}.poutput{padding:12px;background:color-mix(in srgb,var(--ink) 5%,var(--surface));font-size:10px;white-space:pre-wrap}.pprogress{display:inline-grid;border:7px solid color-mix(in srgb,var(--primary) 20%,var(--surface));border-top-color:var(--primary);border-radius:50%;width:95px;height:95px;place-content:center;text-align:center}.pprogress b{font-size:20px}.pprogress span{font-size:8px;color:var(--muted)}.pfeed{padding:13px 0;border-bottom:1px solid color-mix(in srgb,var(--ink) 10%,transparent)}.pfeed h3{font-size:12px;margin:6px 0}.pfeed p{font-size:10px;color:var(--muted)}.phabit{display:flex;gap:10px;align-items:center;padding:13px 0;border-bottom:1px solid color-mix(in srgb,var(--ink) 10%,transparent)}.phabit span{display:grid;gap:3px}.pill{background:var(--primary);color:white;border:0;border-radius:999px;padding:10px 14px;font-weight:700;font-size:10px}.field{border:1px solid color-mix(in srgb,var(--ink) 18%,transparent);background:var(--surface);color:var(--ink);border-radius:7px;padding:10px;font-size:11px}@media(max-width:800px){.pro-shell{grid-template-columns:1fr}.pside{display:none}.pmain{padding:0 14px 25px}.pstats{grid-template-columns:repeat(2,1fr)}.pcards,.pproducts{grid-template-columns:repeat(2,1fr)}.pai-grid,.pcommunity,.pdev{grid-template-columns:1fr}.pboard{grid-template-columns:repeat(3,190px)}}@media(max-width:520px){.pintro{padding:20px 0}.phead{align-items:flex-start;flex-direction:column}.psearch{width:100%;max-width:none}.pproducts,.pcards{grid-template-columns:1fr 1fr}.pform{grid-template-columns:1fr}.pform textarea{grid-column:auto}}';
const side='<aside class="pside"><strong>'+name+'</strong><small>WORKSPACE</small>'+nav.map((x,i)=>'<button class="pnav" data-nav="'+x+'">'+x+'</button>').join("")+'<small style="margin-top:auto">HAxBRO STARTER</small></aside>';
const top='<header class="ptop"><span class="pro-kicker">'+eyebrow+'</span><button class="paction" data-action="Notifications opened">Notifications</button></header>';
return '<style>'+css+'</style><div class="pro-shell">'+side+'<main class="pmain">'+top+'<section class="pintro"><small class="pro-kicker">'+eyebrow+'</small><h1>'+name+'</h1><p>'+desc+'</p></section>'+content+'</main></div><script>(function(){const $=s=>document.querySelector(s);document.querySelectorAll("[data-nav]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-nav]").forEach(x=>x.classList.remove("active"));b.classList.add("active");const h=document.querySelector(".pintro h1");if(h)h.textContent=b.dataset.nav}));document.addEventListener("input",e=>{if(e.target.id==="psearch"){const q=e.target.value.toLowerCase();document.querySelectorAll(".pproduct,.pfeed,.ptable tbody tr").forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))}});document.querySelectorAll(".ptabs button").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll(".ptabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");const out=$("#poutput");if(out)out.textContent=b.textContent+" view selected."}));document.addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(!b)return;const s=$("#pstatus")||$("#poutput");if(s)s.textContent=b.dataset.action+" · Preview interaction completed.";if(b.textContent.includes("Add to basket"))b.textContent="Added"});document.addEventListener("submit",e=>{if(e.target.id!=="pform")return;e.preventDefault();const d=new FormData(e.target),s=$("#pstatus");if($("#precords")){const n=document.createElement("p");n.className="pnote";n.textContent=d.get("query")+" · ₹"+d.get("amount")+" · "+d.get("type");$("#precords").appendChild(n);if(s)s.textContent="Record added to this preview session."}else if($("#pmessages")){const n=document.createElement("p");n.textContent="You: "+d.get("query");$("#pmessages").appendChild(n);if(s)s.textContent="Message added. Connect an AI model for real replies."}else if($("#pfeed")){const n=document.createElement("article");n.className="pfeed";n.textContent="You · "+d.get("query");$("#pfeed").prepend(n);if(s)s.textContent="Post added to this preview session."}else if(s)s.textContent="Request captured in this preview. Connect a backend or provider for live processing.";e.target.reset()})})();</scr'+'ipt>';
}

function browserAIConnectPanel(title,purpose){
const appTitle=esc(title||"AI Assistant"),appPurpose=esc(purpose||"Answer the user's questions helpfully and accurately.");
return `<section class="card section" id="haxbroBrowserAI" style="margin-top:18px"><div class="eyebrow">CONNECT YOUR OWN AI · BROWSER API</div><h2>Paste an AI API key</h2><p class="muted">Connect OpenAI, Groq, OpenRouter or an OpenAI-compatible API. Requests go directly from this browser to the provider — no HAxBRO model or server proxy is required.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin-top:12px"><label class="muted">Provider<select id="haxbroAIProvider" class="field"><option value="openai">OpenAI</option><option value="groq">Groq</option><option value="openrouter">OpenRouter</option><option value="custom">Custom OpenAI-compatible</option></select></label><label class="muted">Model<input id="haxbroAIModel" class="field" value="gpt-4o-mini" autocomplete="off"></label></div><label class="muted" style="display:block;margin-top:10px">API key<input id="haxbroAIKey" class="field" type="password" autocomplete="off" spellcheck="false" placeholder="Paste your own API key"></label><label class="muted" id="haxbroAIEndpointWrap" style="display:none;margin-top:10px">Custom chat-completions endpoint<input id="haxbroAIEndpoint" class="field" type="url" placeholder="https://your-provider.example/v1/chat/completions"></label><div class="row" style="margin-top:12px"><button class="pill" id="haxbroAIConnect" type="button">Connect and chat</button><button class="soft" id="haxbroAIClear" type="button">Clear conversation</button></div><p id="haxbroAIStatus" class="muted" role="status" aria-live="polite">Not connected. Paste your own API key to begin.</p><div id="haxbroAIMessages" class="card" style="min-height:120px;max-height:420px;overflow:auto;margin-top:12px"><p class="muted">Your AI conversation will appear here.</p></div><form id="haxbroAIForm" class="row" style="margin-top:12px"><input id="haxbroAIInput" class="field" style="flex:1" placeholder="Message ${appTitle}…" required><button class="pill" type="submit">Send</button></form><p class="muted" style="font-size:11px;margin-top:10px">Privacy: your key is held only in this page's memory and is sent directly to the provider you select. HAxBRO does not receive or store it. Anyone with access to this browser session may inspect it. Each visitor must use their own key. Provider CORS and account permissions still apply.</p></section><script>(function(){const $=s=>document.querySelector(s),provider=$("#haxbroAIProvider"),model=$("#haxbroAIModel"),key=$("#haxbroAIKey"),endpoint=$("#haxbroAIEndpoint"),endpointWrap=$("#haxbroAIEndpointWrap"),status=$("#haxbroAIStatus"),box=$("#haxbroAIMessages"),form=$("#haxbroAIForm"),input=$("#haxbroAIInput"),connect=$("#haxbroAIConnect"),clear=$("#haxbroAIClear");if(!provider||provider.dataset.ready)return;provider.dataset.ready="1";const system="You are ${appTitle}. Purpose: ${appPurpose}. Be helpful, accurate and follow the user's instructions.";let history=[];const defaults={openai:"gpt-4o-mini",groq:"llama-3.3-70b-versatile",openrouter:"openai/gpt-4o-mini",custom:""};function say(role,content){const row=document.createElement("p");row.className="muted";row.style.whiteSpace="pre-wrap";row.textContent=(role==="user"?"You: ":"AI: ")+content;box.appendChild(row);box.scrollTop=box.scrollHeight}function url(){return provider.value==="openai"?"https://api.openai.com/v1/chat/completions":provider.value==="groq"?"https://api.groq.com/openai/v1/chat/completions":provider.value==="openrouter"?"https://openrouter.ai/api/v1/chat/completions":endpoint.value.trim()}provider.addEventListener("change",()=>{model.value=defaults[provider.value]||"";endpointWrap.style.display=provider.value==="custom"?"block":"none"});clear.addEventListener("click",()=>{history=[];box.textContent="";say("assistant","Conversation cleared. Add a message when you're ready.");status.textContent="Conversation cleared."});async function sendMessage(text){const apiKey=key.value.trim(),modelName=model.value.trim(),target=url();if(!apiKey){status.textContent="Paste your provider API key first.";key.focus();return}if(!modelName){status.textContent="Enter a model name.";model.focus();return}if(!target){status.textContent="Enter a valid custom API endpoint.";endpoint.focus();return}history.push({role:"user",content:text});say("user",text);status.textContent="Sending directly to "+provider.options[provider.selectedIndex].text+"…";connect.disabled=true;try{const headers={"Content-Type":"application/json","Authorization":"Bearer "+apiKey};if(provider.value==="openrouter"){headers["HTTP-Referer"]=location.origin;headers["X-Title"]=document.title||"HAxBRO generated AI"}const response=await fetch(target,{method:"POST",headers,body:JSON.stringify({model:modelName,messages:[{role:"system",content:system},...history.slice(-20)]})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||data.error||"Provider request failed ("+response.status+").");const reply=data.choices?.[0]?.message?.content;if(typeof reply!=="string"||!reply.trim())throw new Error("The provider returned no message content.");history.push({role:"assistant",content:reply});say("assistant",reply);status.textContent="Connected · "+provider.options[provider.selectedIndex].text+" · "+modelName}catch(error){const message=String(error.message||error);say("assistant","Request failed: "+message);status.textContent=/failed to fetch|networkerror|cors/i.test(message)?"Browser could not reach this provider. Check provider CORS, endpoint and network settings.":message}finally{connect.disabled=false}}connect.addEventListener("click",()=>{const text=input.value.trim();if(text){input.value="";sendMessage(text)}else{status.textContent="Type a message below, then press Send." ;input.focus()}});form.addEventListener("submit",e=>{e.preventDefault();const text=input.value.trim();if(!text)return;input.value="";sendMessage(text)});})();</script>`;
}
