if(String(t.kind).indexOf('ai-')===0){body+='<script>(function(){const $=s=>document.querySelector(s);const name=$("#aiName"),purpose=$("#aiPurpose"),color=$("#aiColor"),title=document.querySelector(".hero h1"),messages=$("#aiMessages"),apiKey=$("#aiApiKey"),provider=$("#aiProvider"),model=$("#aiModel"),connectStatus=$("#aiConnectStatus");let chatHistory=[];function say(text,who){const p=document.createElement("p");p.textContent=(who==="you"?"You: ":"AI: ")+text;messages.appendChild(p);messages.scrollTop=messages.scrollHeight}function askKai(text){const requestId="ai-"+Date.now()+"-"+Math.random().toString(36).slice(2);parent.postMessage({type:"haxbro:kai-chat-request",requestId,message:text,history:[]},"*");}function askProvider(text){if(!apiKey||!apiKey.value.trim()){if(connectStatus)connectStatus.textContent="Add your provider API key above to enable real AI replies.";say("Connect OpenAI, Groq or OpenRouter with your API key before chatting.","kai");return}const payload={provider:provider.value,model:model.value,apiKey:apiKey.value,message:text,systemPrompt:"You are "+(name?.value||"My AI")+". Personality: "+($("#aiTone")?.value||"Helpful and clear")+". Purpose: "+(purpose?.value||"Be a helpful AI assistant")+". Answer the user directly and follow this purpose.",history:chatHistory};if(window.parent===window){if(connectStatus)connectStatus.textContent="Sending to "+provider.value+"…";fetch("https://haxbro-ai-oybr.hatchable.site/api/ai-chat",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)}).then(async r=>{const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||"AI provider request failed");chatHistory.push({role:"assistant",content:String(d.response||"")});say(d.response||"The provider returned an empty answer.","kai");if(connectStatus)connectStatus.textContent="AI connected · "+(d.provider||provider.value)+" · "+(d.model||model.value)}).catch(e=>{say(e.message||"AI provider connection failed.","kai");if(connectStatus)connectStatus.textContent=e.message||"Provider connection failed."});return}const requestId="provider-"+Date.now()+"-"+Math.random().toString(36).slice(2);parent.postMessage({type:"haxbro:ai-provider-chat-request",requestId,...payload},"*");if(connectStatus)connectStatus.textContent="Connected for this preview session. Waiting for the model…"}window.addEventListener("message",e=>{if(e.data&&e.data.type==="haxbro:kai-chat-response"){say(e.data.response||e.data.error||"KAI did not return a response.","kai")}if(e.data&&e.data.type==="haxbro:ai-provider-chat-response"){const d=e.data;if(d.response){chatHistory.push({role:"assistant",content:String(d.response)});say(d.response,"kai");if(connectStatus)connectStatus.textContent="AI is connected · "+(d.provider||provider.value)+" · "+(d.model||model.value)}else{say(d.error||"The AI provider could not answer.","kai");if(connectStatus)connectStatus.textContent=d.error||"Provider connection failed."}}});provider?.addEventListener("change",()=>{if(model)model.value=provider.value==="groq"?"llama-3.3-70b-versatile":provider.value==="openrouter"?"openai/gpt-4o-mini":"gpt-4o-mini"});$("#saveAiSetup")?.addEventListener("click",()=>{if(title&&name.value)title.textContent=name.value;color?.addEventListener("input",()=>document.documentElement.style.setProperty("--primary",color.value));document.documentElement.style.setProperty("--primary",color.value);$("#aiSetupStatus").textContent="Your setup is saved in this preview. Add a provider API key above to enable real AI replies; the key is not saved."});$("#askKaiAi")?.addEventListener("click",()=>{const caps=[...document.querySelectorAll(".section input[type=checkbox]:checked")].map(x=>x.parentElement.textContent.trim());const instruction="Customize this existing AI application in place. AI name: "+(name?.value||"My AI")+". Purpose: "+(purpose?.value||"Build a helpful AI assistant")+". Personality: "+($("#aiTone")?.value||"Helpful and clear")+". Primary color: "+(color?.value||"blue")+". Capabilities: "+caps.join(", ")+". Build the appropriate editable interface, configuration and functional interactions. Preserve the current project and do not replace it with a generic landing page.";say(instruction,"you");askKai(instruction)});$("#aiChatForm")?.addEventListener("submit",e=>{e.preventDefault();const input=$("#aiChatInput");if(!input.value.trim())return;const msg=input.value.trim();say(msg,"you");chatHistory.push({role:"user",content:msg});askProvider(msg);input.value=""})})();</scr'+'ipt>';}

return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(t.name)+'</title>'+common+'</head><body>'+(t.kind==='pro-template'?body:'<main class="app"><header class="nav"><div class="brand">'+esc(t.name)+'</div><div class="toolbar"><button class="soft">Overview</button><button class="pill">Get started</button></div></header>'+body+'<footer class="footer">Made with HAxBRO · Customize this application with KAI</footer></main>')+'<script>document.addEventListener("click",function(e){const b=e.target.closest("[data-key]");if(b){const d=document.querySelector("#display");if(!d)return;let v=b.dataset.key;if(v==="C")d.value="0";else if(v==="="){try{d.value=String(Function("return ("+d.value.replace(/[÷×−]/g,x=>({"÷":"/","×":"*","−":"-"}[x]))+")")())}catch{d.value="Error"}}else d.value=d.value==="0"?v:d.value+v}if(e.target.closest(".addCart")){let c=document.querySelector("#cart");if(c){let n=Number(c.dataset.count||0)+1;c.dataset.count=n;c.textContent="Cart · "+n}}if(e.target.matches("[data-answer]")){document.querySelector("#quizResult").textContent=e.target.dataset.answer==="Mars"?"Correct!":"Not quite — try again."}});document.addEventListener("submit",function(e){e.preventDefault();if(e.target.id==="chatForm"){const input=document.querySelector("#chatInput"),box=document.querySelector("#messages");if(input&&input.value.trim()){const p=document.createElement("p");p.textContent=input.value;box.appendChild(p);input.value=""}}if(e.target.id==="expenseForm"){const n=document.querySelector("#expenseName"),a=document.querySelector("#expenseAmount"),ul=document.querySelector("#expenses");if(n.value&&a.value){const li=document.createElement("li");li.textContent=n.value+" — $"+a.value;ul.appendChild(li);n.value="";a.value=""}}});document.querySelector("#formatJson")?.addEventListener("click",()=>{try{document.querySelector("#jsonOutput").textContent=JSON.stringify(JSON.parse(document.querySelector("#jsonInput").value),null,2)}catch(e){document.querySelector("#jsonOutput").textContent="Invalid JSON: "+e.message}});document.querySelector("#clearJson")?.addEventListener("click",()=>{document.querySelector("#jsonInput").value="";document.querySelector("#jsonOutput").textContent=""});document.querySelector("#proSearch")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();document.querySelectorAll(".pro-item").forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(q)})});document.addEventListener("click",e=>{const b=e.target.closest(".pro-action");if(!b)return;const status=document.querySelector("#proStatus");if(status)status.textContent=b.dataset.action+" · Demo interaction completed.";if(b.textContent.trim()==="Add")b.textContent="Added"});document.querySelector("#proForm")?.addEventListener("submit",e=>{e.preventDefault();const data=new FormData(e.currentTarget);const status=document.querySelector("#proStatus");if(status)status.textContent="Request captured in this preview: "+(data.get("query")||"Your request")+". Connect a backend to process real bookings or records.";const list=document.querySelector("#proRecords");if(list){const li=document.createElement("li");li.textContent=(data.get("query")||"New record")+" — "+(data.get("amount")||data.get("quantity")||"1");list.appendChild(li)}e.currentTarget.reset()});</script></body></html>';
